import {
  AlertTriangle, ArrowUpRight, Bell, Camera, CheckCircle2, ClipboardList, Clock3, FileDown,
  ImagePlus, LayoutDashboard, MapPin, Menu, PackageOpen, Plus, Search,
  Settings2, ShieldCheck, Users2, Wrench, X,
} from "lucide-react";
