const roleLabels: Record<string, string> = { ADMIN: "ผู้ดูแลระบบ", REPORTER: "ผู้แจ้งงาน", SUPERVISOR: "หัวหน้างาน", TECHNICIAN: "ช่างเทคนิค" };
const statusLabels: Record<string, string> = { OPEN: "เปิดงาน", ASSIGNED: "มอบหมายแล้ว", IN_PROGRESS: "กำลังดำเนินการ", PENDING_PARTS: "รออะไหล่", COMPLETED: "เสร็จงาน", CLOSED: "ปิดงาน" };
const statusTone: Record<string, string> = {
  OPEN: "bg-sky-50 text-sky-800 ring-sky-200", ASSIGNED: "bg-violet-50 text-violet-800 ring-violet-200",
  IN_PROGRESS: "bg-amber-50 text-amber-800 ring-amber-200", PENDING_PARTS: "bg-orange-50 text-orange-800 ring-orange-200",
  COMPLETED: "bg-emerald-50 text-emerald-800 ring-emerald-200", CLOSED: "bg-slate-100 text-slate-700 ring-slate-200",
};
const availabilityLabels: Record<string, string> = { ON_DUTY: "เข้าเวร", OFF_DUTY: "ออกเวร", ON_LEAVE: "ลาหยุด" };
const availabilityTone: Record<string, string> = { ON_DUTY: "bg-emerald-50 text-emerald-800 ring-emerald-200", OFF_DUTY: "bg-slate-100 text-slate-700 ring-slate-200", ON_LEAVE: "bg-rose-50 text-rose-800 ring-rose-200" };

function formatDate(value: unknown, full = false) {
  return value ? new Date(value as string).toLocaleString("th-TH", full ? { dateStyle: "medium", timeStyle: "short" } : { day: "2-digit", month: "short" }) : "—";
}
function initials(name?: string | null) { return (name ?? "ผู้ใช้").split(" ").map(word => word[0]).join("").slice(0, 2).toUpperCase(); }
function StatusPill({ status }: { status: string }) { return <span className={cn("inline-flex shrink-0 rounded-full px-2.5 py-1 text-[10px] font-bold ring-1 ring-inset", statusTone[status] ?? statusTone.OPEN)}>{statusLabels[status] ?? status}</span>; }
function AccessNotice({ title, children }: { title: string; children: React.ReactNode }) { return <Card className="border-amber-300/20 bg-amber-400/10 text-amber-50"><CardContent className="flex gap-3 p-5"><AlertTriangle className="h-5 w-5 shrink-0 text-amber-200" /><div><p className="font-semibold">{title}</p><p className="mt-1 text-sm leading-6 text-amber-100/80">{children}</p></div></CardContent></Card>; }

function LoginShell({ children }: { children: React.ReactNode }) { return <div className="flex min-h-screen items-center justify-center bg-[radial-gradient(circle_at_15%_15%,rgba(45,212,191,.18),transparent_30%),radial-gradient(circle_at_85%_85%,rgba(99,102,241,.20),transparent_28%),#090d1b] p-4"><main className="w-full max-w-md rounded-[2rem] border border-white/10 bg-slate-950/85 p-6 text-slate-100 shadow-2xl shadow-black/30 backdrop-blur-xl sm:p-8">{children}</main></div>; }
function LoginScreen() { return <LoginShell><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-gradient-to-br from-teal-300 to-cyan-400 text-slate-950 shadow-lg shadow-teal-900/20"><Wrench className="h-6 w-6" /></div><p className="mt-7 text-[11px] font-bold tracking-[.22em] text-teal-300">NORTHSTAR HOTEL</p><h1 className="mt-2 text-2xl font-bold tracking-tight text-white">ศูนย์งานซ่อมบำรุง</h1><p className="mt-3 text-sm leading-6 text-slate-300">เข้าสู่ระบบด้วย LINE เพื่อแจ้งซ่อม ติดตามงาน และบันทึกหลักฐานการปฏิบัติงาน</p><a className="mt-7 flex h-12 items-center justify-center rounded-xl bg-[#06C755] text-sm font-bold text-white shadow-lg shadow-emerald-900/15 hover:bg-[#05b64c]" href={`/api/auth/line/start?returnTo=${encodeURIComponent(`${window.location.pathname}${window.location.search}`)}`}>เข้าสู่ระบบด้วย LINE</a></LoginShell>; }
function Registration({ name, pending, error, onSubmit }: { name: string; pending: boolean; error?: string; onSubmit: (event: React.FormEvent<HTMLFormElement>) => void }) { return <LoginShell><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-teal-300/10 text-teal-200"><Users2 className="h-6 w-6" /></div><p className="mt-7 text-[11px] font-bold tracking-[.22em] text-teal-300">ลงทะเบียนครั้งแรก</p><h1 className="mt-2 text-2xl font-bold tracking-tight text-white">ข้อมูลผู้ใช้งาน</h1><p className="mt-3 text-sm leading-6 text-slate-300">ข้อมูลนี้ใช้ระบุผู้แจ้งในใบงานโดยอัตโนมัติ</p><form className="mt-7 space-y-4" onSubmit={onSubmit}><label className="block text-sm font-semibold">ชื่อที่แสดง<Input required name="displayName" defaultValue={name} className="mt-2 h-11 rounded-xl border-white/10 bg-white/5 text-white" /></label><label className="block text-sm font-semibold">แผนก<select required name="department" defaultValue="" className="mt-2 h-11 w-full rounded-xl border border-white/10 bg-slate-900 px-3 text-sm"><option value="" disabled>เลือกแผนก</option><option value="FRONT_OFFICE">แผนกต้อนรับ</option><option value="HOUSEKEEPING">แผนกแม่บ้าน</option><option value="FOOD_AND_BEVERAGE">แผนกอาหารและเครื่องดื่ม</option><option value="ENGINEERING">แผนกช่างและวิศวกรรม</option><option value="SECURITY">แผนกรักษาความปลอดภัย</option><option value="FINANCE">แผนกการเงิน</option><option value="ADMINISTRATION">แผนกบริหาร</option><option value="OTHER">อื่น ๆ</option></select></label>{error && <p className="rounded-xl bg-rose-400/15 p-3 text-sm text-rose-100">{error}</p>}<Button disabled={pending} className="h-11 w-full rounded-xl bg-gradient-to-r from-teal-400 to-cyan-400 font-bold text-slate-950 hover:from-teal-300 hover:to-cyan-300">{pending ? "กำลังบันทึก..." : "บันทึกและเริ่มใช้งาน"}</Button></form></LoginShell>; }

function AvailabilityPill({ status }: { status?: string | null }) { const safeStatus = status ?? "OFF_DUTY"; return <span className={cn("rounded-full px-2.5 py-1 text-[10px] font-bold ring-1 ring-inset", availabilityTone[safeStatus] ?? availabilityTone.OFF_DUTY)}>{availabilityLabels[safeStatus] ?? safeStatus}</span>; }

function TechnicianPanel({ technicians }: { technicians: any[] }) {
  const { user } = useAuth(); const utils = trpc.useUtils(); const isManager = ["ADMIN", "SUPERVISOR"].includes(user?.role ?? "");
  const updateAvailability = trpc.technicians.setAvailability.useMutation({ onSuccess: async () => { await utils.technicians.list.invalidate(); toast.success("อัปเดตสถานะเวรแล้ว"); }, onError: error => toast.error(`อัปเดตสถานะเวรไม่สำเร็จ: ${error.message}`) });
  const currentTech = technicians.find(technician => technician.techId === user?.openId || technician.userId === user?.openId || technician.lineUserId === user?.openId);
  return <div className="space-y-5">
    <Card className="border-cyan-300/15 bg-gradient-to-br from-cyan-500/15 via-slate-950 to-violet-500/10 text-slate-100"><CardContent className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between"><div className="flex gap-4"><Wrench className="mt-0.5 h-8 w-8 shrink-0 text-cyan-200" /><div><p className="text-xs font-bold tracking-wide text-cyan-200">หน้าช่างและสถานะเวร</p><h3 className="mt-1 text-lg font-bold">สถานะเวรใช้ประกอบการเลือกผู้รับผิดชอบ</h3><p className="mt-1 max-w-2xl text-sm leading-6 text-slate-300">ถ้ามีช่างเข้าเวรและพร้อมรับงานเพียงคนเดียว ระบบจะมอบหมายให้อัตโนมัติ; หากมีหลายคน Supervisor หรือ Admin จะเป็นผู้เลือกและยืนยันเอง</p></div></div>{currentTech && <AvailabilityPill status={currentTech.availabilityStatus} />}</CardContent></Card>
    {user?.role === "TECHNICIAN" && <Card className="border-teal-300/20 bg-teal-400/10 text-slate-100"><CardContent className="p-5"><p className="text-xs font-bold text-teal-200">สถานะเวรของฉัน</p>{currentTech ? <><div className="mt-2 flex items-center justify-between gap-3"><div><p className="font-bold">{currentTech.techName}</p><p className="mt-1 text-xs text-slate-300">เปลี่ยนทันทีเมื่อเริ่มงาน เลิกงาน หรือมีวันลา</p></div><AvailabilityPill status={currentTech.availabilityStatus} /></div><div className="mt-4 grid gap-2 sm:grid-cols-3">{["ON_DUTY", "OFF_DUTY", "ON_LEAVE"].map(status => <Button key={status} type="button" variant="outline" disabled={updateAvailability.isPending || currentTech.availabilityStatus === status} onClick={() => updateAvailability.mutate({ techId: currentTech.techId, availabilityStatus: status as "ON_DUTY" | "OFF_DUTY" | "ON_LEAVE" })} className={cn("h-10 border-white/15 bg-slate-950/20 text-slate-100 hover:bg-white/10", currentTech.availabilityStatus === status && "border-teal-300/70 bg-teal-300/15 text-teal-100")}>{availabilityLabels[status]}</Button>)}</div></> : <p className="mt-2 text-sm text-amber-100">บัญชีนี้ยังไม่มีข้อมูลช่าง โปรดให้ Admin กำหนดบทบาท TECHNICIAN ในเมนูผู้ใช้งาน</p>}</CardContent></Card>}
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{technicians.map(technician => { const mayEdit = isManager || technician.techId === currentTech?.techId; return <Card key={technician.techId} className="border-white/10 bg-slate-950/60 text-slate-100 shadow-sm"><CardContent className="p-5"><div className="flex items-start justify-between gap-3"><div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-teal-300/10 text-teal-200"><Wrench className="h-5 w-5" /></div><AvailabilityPill status={technician.availabilityStatus} /></div><h3 className="mt-4 font-bold">{technician.techName}</h3><p className="mt-1 text-sm text-slate-400">{technician.teamCode ?? "MAINTENANCE"}</p><div className="mt-4 rounded-xl bg-white/5 p-3 text-xs text-slate-300"><span className="font-bold text-white">{technician.currentOpenJobs ?? 0}</span> / {technician.maxOpenJobs ?? 5} งานที่เปิดอยู่</div>{mayEdit && <select aria-label={`สถานะเวร ${technician.techName}`} value={technician.availabilityStatus ?? "OFF_DUTY"} disabled={updateAvailability.isPending} onChange={event => updateAvailability.mutate({ techId: technician.techId, availabilityStatus: event.target.value as "ON_DUTY" | "OFF_DUTY" | "ON_LEAVE" })} className="mt-3 h-9 w-full rounded-lg border border-white/10 bg-slate-900 px-2 text-xs text-slate-100"><option value="ON_DUTY">เข้าเวร</option><option value="OFF_DUTY">ออกเวร</option><option value="ON_LEAVE">ลาหยุด</option></select>}</CardContent></Card>; })}</div>
  </div>;
}

function PhotoGroup({ label, files, type, note, onUpload }: { label: string; files: any[]; type: "BEFORE" | "AFTER"; note: string; onUpload: (event: React.ChangeEvent<HTMLInputElement>, type: "BEFORE" | "AFTER") => void }) { return <div className="rounded-2xl border border-white/10 bg-white/[.035] p-3"><div className="flex items-start justify-between gap-3"><div><p className="flex items-center gap-2 text-sm font-bold"><Camera className="h-4 w-4 text-teal-200" />{label}</p><p className="mt-1 text-[11px] leading-4 text-slate-400">{note}</p></div><div className="flex flex-wrap gap-2"><label className="inline-flex h-9 shrink-0 cursor-pointer items-center gap-1 rounded-lg bg-white/10 px-2.5 text-xs font-bold text-teal-100 hover:bg-white/15"><Camera className="h-3.5 w-3.5" /><span>ถ่ายรูป</span><input className="hidden" type="file" accept="image/*" capture="environment" onChange={event => onUpload(event, type)} /></label><label className="inline-flex h-9 shrink-0 cursor-pointer items-center gap-1 rounded-lg bg-white/10 px-2.5 text-xs font-bold text-teal-100 hover:bg-white/15"><ImagePlus className="h-3.5 w-3.5" /><span>เลือกจากคลังภาพ</span><input className="hidden" type="file" accept="image/*" multiple onChange={event => onUpload(event, type)} /></label></div></div><div className="mt-3 grid grid-cols-3 gap-2">{files.map((file: any) => <a key={file.attachmentId} href={file.fileUrl} target="_blank" rel="noreferrer" className="aspect-square overflow-hidden rounded-xl bg-slate-800"><img src={file.fileUrl} alt={file.fileName} className="h-full w-full object-cover" /></a>)}{files.length === 0 && <div className="col-span-3 rounded-xl border border-dashed border-white/10 bg-white/[.035] p-3 text-center text-xs text-slate-400">ยังไม่มีรูปภาพ</div>}</div></div>; }

function PartIssuePanel({ woId, status, onSetPending, pendingLoading }: { woId: string; status: string; onSetPending: () => void; pendingLoading: boolean }) {
  const { user } = useAuth(); const utils = trpc.useUtils(); const canRequest = ["TECHNICIAN", "SUPERVISOR", "ADMIN"].includes(user?.role ?? ""); const canManage = ["SUPERVISOR", "ADMIN"].includes(user?.role ?? "");
  const [requestOpen, setRequestOpen] = useState(false); const issues = trpc.partIssues.list.useQuery({ woId }); const parts = trpc.parts.list.useQuery(undefined, { enabled: requestOpen && canRequest });
  const request = trpc.partIssues.request.useMutation({ onSuccess: async () => { await utils.partIssues.list.invalidate({ woId }); setRequestOpen(false); toast.success("ส่งคำขอเบิกอะไหล่แล้ว"); }, onError: error => toast.error(`ส่งคำขอไม่สำเร็จ: ${error.message}`) });
  const approve = trpc.partIssues.approve.useMutation({ onSuccess: () => utils.partIssues.list.invalidate({ woId }) }); const issue = trpc.partIssues.issue.useMutation({ onSuccess: () => utils.partIssues.list.invalidate({ woId }) }); const issueConsumable = trpc.partIssues.issueConsumable.useMutation({ onSuccess: async () => { await Promise.all([utils.partIssues.list.invalidate({ woId }), utils.parts.list.invalidate()]); } });
  const issueRows = issues.data ?? [];
  return <section className="rounded-2xl border border-orange-300/20 bg-orange-400/[.06] p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-bold text-orange-100">เบิกอะไหล่สำหรับใบงานนี้</p><p className="mt-1 text-xs leading-5 text-slate-400">ทุกคำขออ้างอิงเลขใบงาน {woId} โดยตรง</p></div><div className="flex flex-wrap gap-2">{["ASSIGNED", "IN_PROGRESS"].includes(status) && canRequest && <Button type="button" onClick={onSetPending} disabled={pendingLoading} variant="outline" className="h-9 rounded-xl border-orange-300/40 bg-orange-400/10 text-orange-100 hover:bg-orange-400/20">{pendingLoading ? "กำลังบันทึก..." : "ตั้งเป็นรออะไหล่"}</Button>}{canRequest && <Button type="button" onClick={() => setRequestOpen(true)} className="h-9 rounded-xl bg-orange-400 text-slate-950 hover:bg-orange-300"><Plus className="mr-1 h-4 w-4" />ขอเบิกอะไหล่</Button>}</div></div>{issueRows.length === 0 ? <p className="mt-4 rounded-xl border border-dashed border-white/10 bg-slate-950/20 p-3 text-center text-xs text-slate-400">ยังไม่มีรายการเบิกอะไหล่สำหรับใบงานนี้</p> : <div className="mt-4 space-y-2">{issueRows.map((item: any) => <div key={item.issueId} className="rounded-xl border border-white/10 bg-slate-950/35 p-3"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="text-sm font-semibold text-slate-100">{item.partNameTh}</p><p className="mt-1 text-xs text-slate-400">{item.partCode} · ขอ {item.qtyRequested} {item.unit} · อนุมัติ {item.qtyApproved} · จ่าย {item.qtyIssued}</p>{item.notes && <p className="mt-1 text-xs text-slate-400">หมายเหตุ: {item.notes}</p>}</div><span className={cn("rounded-full px-2 py-1 text-[10px] font-bold", item.issueStatus === "ISSUED" ? "bg-emerald-400/15 text-emerald-200" : item.issueStatus === "APPROVED" ? "bg-sky-400/15 text-sky-200" : "bg-amber-400/15 text-amber-100")}>{item.issueStatus === "ISSUED" ? "จ่ายแล้ว" : item.issueStatus === "APPROVED" ? "อนุมัติแล้ว" : "รออนุมัติ"}</span></div>{canManage && item.issueStatus === "REQUESTED" && /(CONSUMABLE|DISPOSABLE|SUPPLY|วัสดุสิ้นเปลือง)/i.test(item.categoryCode ?? "") && <Button size="sm" type="button" variant="outline" onClick={() => issueConsumable.mutate({ issueId: item.issueId, qtyIssued: item.qtyRequested })} disabled={issueConsumable.isPending} className="mt-3 h-8 border-emerald-300/30 bg-emerald-400/10 text-emerald-100">เบิกวัสดุสิ้นเปลืองทันที</Button>}{canManage && item.issueStatus === "REQUESTED" && !/(CONSUMABLE|DISPOSABLE|SUPPLY|วัสดุสิ้นเปลือง)/i.test(item.categoryCode ?? "") && <Button size="sm" type="button" variant="outline" onClick={() => approve.mutate({ issueId: item.issueId, qtyApproved: item.qtyRequested })} disabled={approve.isPending} className="mt-3 h-8 border-sky-300/30 bg-sky-400/10 text-sky-100">อนุมัติจำนวนที่ขอ</Button>}{canManage && item.issueStatus === "APPROVED" && <Button size="sm" type="button" variant="outline" onClick={() => issue.mutate({ issueId: item.issueId, qtyIssued: item.qtyApproved })} disabled={issue.isPending} className="mt-3 h-8 border-emerald-300/30 bg-emerald-400/10 text-emerald-100">ยืนยันการจ่าย</Button>}</div>)}</div>}
    <Dialog open={requestOpen} onOpenChange={setRequestOpen}><DialogContent className="w-[calc(100%-1.25rem)] rounded-3xl border-white/10 bg-slate-950 p-5 text-slate-100 sm:max-w-md"><DialogHeader><DialogTitle>ขอเบิกอะไหล่ · {woId}</DialogTitle></DialogHeader><form className="space-y-4 pt-2" onSubmit={event => { event.preventDefault(); const form = new FormData(event.currentTarget); request.mutate({ woId, partId: String(form.get("partId")), qtyRequested: Number(form.get("qty")), notes: String(form.get("notes") || "") || undefined }); }}><label className="block text-sm font-semibold">อะไหล่<select required name="partId" defaultValue="" className="mt-2 h-11 w-full rounded-xl border border-white/10 bg-slate-900 px-3 text-sm"><option value="" disabled>เลือกอะไหล่</option>{(parts.data ?? []).filter((part: any) => part.isActive).map((part: any) => <option key={part.partId} value={part.partId}>{part.partNameTh} · คงเหลือ {part.availableQty} {part.unit}</option>)}</select></label><label className="block text-sm font-semibold">จำนวน<Input required min={1} type="number" name="qty" defaultValue={1} className="mt-2 h-11 border-white/10 bg-slate-900 text-white" /></label><label className="block text-sm font-semibold">หมายเหตุ<Textarea name="notes" className="mt-2 border-white/10 bg-slate-900 text-white" placeholder="ระบุเหตุผลหรือรายละเอียดเพิ่มเติม" /></label><Button type="submit" disabled={request.isPending} className="h-10 w-full bg-orange-400 text-slate-950 hover:bg-orange-300">{request.isPending ? "กำลังส่งคำขอ..." : "ส่งคำขอเบิก"}</Button></form></DialogContent></Dialog></section>;
}

function PendingPartsPdf({ order }: { order: any }) {
  const [reportUrl, setReportUrl] = useState("");
  const createReport = trpc.workOrders.createPendingPartsReportPdf.useMutation({
    onSuccess: result => {
      setReportUrl(result.url);
      toast.success("สร้างรายงาน PDF และบันทึกลง Google Drive แล้ว");
    },
    onError: error => toast.error(`สร้าง PDF ไม่สำเร็จ: ${error.message}`),
  });
  return <div className="flex flex-wrap items-center gap-2">
    <Button type="button" onClick={() => { setReportUrl(""); createReport.mutate({ woId: order.woId }); }} disabled={createReport.isPending} className="h-10 rounded-xl bg-orange-400 text-slate-950 hover:bg-orange-300">
      <FileDown className="mr-1.5 h-4 w-4" />{createReport.isPending ? "กำลังสร้างและบันทึก..." : "สร้าง PDF ลง Google Drive"}
    </Button>
    {reportUrl && <a href={reportUrl} target="_blank" rel="noreferrer" className="inline-flex h-10 items-center rounded-xl border border-sky-300/30 bg-sky-400/10 px-3 text-xs font-semibold text-sky-100 hover:bg-sky-400/20">เปิดรายงานใน Drive</a>}
  </div>;
}

function WorkOrderDetail({ order, locations, technicians, data, onClose, onUpload }: { order: any; locations: any[]; technicians: any[]; data: any; onClose: () => void; onUpload: (event: React.ChangeEvent<HTMLInputElement>, type: "BEFORE" | "AFTER" | "OTHER") => void }) {
  const { user } = useAuth(); const utils = trpc.useUtils(); const [error, setError] = useState(""); const isManager = ["ADMIN", "SUPERVISOR"].includes(user?.role ?? "");
  const attachments = data?.attachments ?? []; const before = attachments.filter((file: any) => file.attachmentType === "BEFORE"); const after = attachments.filter((file: any) => file.attachmentType === "AFTER");
  const change = trpc.workOrders.changeStatus.useMutation({ onSuccess: () => { utils.workOrders.list.invalidate(); utils.workOrders.detail.invalidate({ woId: order.woId }); }, onError: err => setError(err.message === "AFTER_PHOTO_REQUIRED" ? "เพิ่มรูปหลังเสร็จงานอย่างน้อย 1 รูปก่อนทำเครื่องหมายว่าเสร็จ" : err.message) });
  const pending = trpc.workOrders.setPendingParts.useMutation({ onSuccess: () => { utils.workOrders.list.invalidate(); utils.workOrders.detail.invalidate({ woId: order.woId }); toast.success("เปลี่ยนสถานะเป็นรออะไหล่แล้ว"); }, onError: err => setError(err.message) });
  const assign = trpc.workOrders.assign.useMutation({ onSuccess: () => { utils.workOrders.list.invalidate(); utils.workOrders.detail.invalidate({ woId: order.woId }); utils.technicians.list.invalidate(); toast.success("ยืนยันการมอบหมายงานแล้ว"); }, onError: err => setError(err.message) });
  const canSetCategory = ["TECHNICIAN", "SUPERVISOR", "ADMIN"].includes(user?.role ?? "");
  const updateCategory = trpc.workOrders.update.useMutation({ onSuccess: () => { utils.workOrders.list.invalidate(); utils.workOrders.detail.invalidate({ woId: order.woId }); toast.success("บันทึกหมวดหมู่ใบงานแล้ว"); }, onError: err => setError(err.message) });
  const candidates = getManualAssignmentCandidates(technicians); const locationName = locations.find(item => item.locationId === order.locationId)?.areaName ?? order.locationId;
  const go = (toStatus: string) => { setError(""); change.mutate({ woId: order.woId, fromStatus: order.statusCode, toStatus: toStatus as any, actorUserId: user?.openId ?? "", comment: toStatus === "IN_PROGRESS" ? "เริ่มดำเนินการ" : toStatus === "COMPLETED" ? "ดำเนินการเสร็จแล้ว" : "ปิดใบงาน" }); };
  return <Dialog open onOpenChange={open => !open && onClose()}><DialogContent className="max-h-[92vh] w-[calc(100%-1rem)] overflow-y-auto rounded-3xl border-white/10 bg-slate-950 p-4 text-slate-100 shadow-2xl shadow-black/40 sm:max-w-3xl sm:p-6"><DialogHeader><div className="flex items-center justify-between gap-3 pr-6"><div><DialogTitle>{order.woId}</DialogTitle><p className="mt-1 text-xs text-slate-400">{locationName}</p></div><StatusPill status={order.statusCode} /></div></DialogHeader><div className="space-y-4 pt-3"><div className="rounded-2xl bg-white/[.045] p-4"><p className="text-xs font-bold text-slate-400">รายละเอียด</p><p className="mt-2 text-sm leading-6 text-slate-100">{order.description}</p></div>{canSetCategory && <form className="rounded-2xl border border-cyan-300/15 bg-cyan-400/[.05] p-4" onSubmit={event => { event.preventDefault(); const categoryCode = String(new FormData(event.currentTarget).get("categoryCode") ?? "").trim(); if (!categoryCode) { setError("กรุณาระบุหมวดหมู่ใบงาน"); return; } setError(""); updateCategory.mutate({ woId: order.woId, values: { categoryCode } }); }}><label className="block text-xs font-bold text-cyan-100">หมวดหมู่ใบงาน (ช่าง / หัวหน้างาน / ผู้ดูแล)<Input name="categoryCode" required maxLength={80} defaultValue={order.categoryCode ?? "UNSPECIFIED"} className="mt-2 h-10 border-white/15 bg-slate-900 text-sm text-white" /></label><Button type="submit" disabled={updateCategory.isPending} className="mt-3 h-9 rounded-xl bg-cyan-300 text-slate-950 hover:bg-cyan-200">{updateCategory.isPending ? "กำลังบันทึก..." : "บันทึกหมวดหมู่"}</Button></form>}<div className="grid gap-3 sm:grid-cols-2"><PhotoGroup label="รูปก่อนเริ่มงาน" files={before} type="BEFORE" note="บันทึกสภาพก่อนปฏิบัติงาน" onUpload={onUpload} /><PhotoGroup label="รูปหลังเสร็จงาน" files={after} type="AFTER" note="จำเป็นก่อนเปลี่ยนสถานะเป็นเสร็จงาน" onUpload={onUpload} /></div><PartIssuePanel woId={order.woId} status={order.statusCode} onSetPending={() => pending.mutate({ woId: order.woId, comment: "รออะไหล่จากหน้าใบงาน" })} pendingLoading={pending.isPending} />{error && <p className="rounded-xl bg-rose-400/15 p-3 text-sm text-rose-100">{error}</p>}{isManager && (!order.assignedTechId || candidates.length > 1) ? <form className="rounded-2xl border border-violet-300/20 bg-violet-400/[.08] p-4" onSubmit={event => { event.preventDefault(); const values = new FormData(event.currentTarget); const techId = String(values.get("techId") || ""); if (!techId) { setError("โปรดเลือกช่างที่เข้าเวรก่อนยืนยันการมอบหมาย"); return; } assign.mutate({ woId: order.woId, techId, assignedTeam: null, actorUserId: user?.openId ?? "", comment: "Supervisor/Admin ยืนยันการมอบหมายจากหน้าใบงาน" }); }}><p className="text-xs font-bold text-violet-200">มอบหมายช่าง</p><p className="mt-1 text-xs leading-5 text-slate-300">{getManualAssignmentHint(candidates.length)}</p><div className="mt-3 flex flex-col gap-2 sm:flex-row"><select required name="techId" defaultValue={order.assignedTechId ?? ""} className="h-10 min-w-0 flex-1 rounded-xl border border-violet-300/20 bg-slate-950 px-3 text-sm text-slate-100"><option value="" disabled>เลือกช่างเข้าเวร</option>{order.assignedTechId && !candidates.some(candidate => candidate.techId === order.assignedTechId) && <option value={order.assignedTechId}>ช่างที่มอบหมายเดิม</option>}{candidates.map(candidate => <option key={candidate.techId} value={candidate.techId}>{candidate.techName} · รับอยู่ {candidate.currentOpenJobs ?? 0}/{candidate.maxOpenJobs ?? 5} งาน</option>)}</select><Button disabled={assign.isPending || candidates.length === 0} className="h-10 rounded-xl bg-violet-400 text-slate-950 hover:bg-violet-300">{assign.isPending ? "กำลังยืนยัน..." : "ยืนยันการมอบหมาย"}</Button></div></form> : <div className="rounded-xl border border-white/10 bg-white/[.035] p-3 text-xs leading-5 text-slate-400">{order.assignedTechId ? `มอบหมายให้ ${technicians.find(tech => tech.techId === order.assignedTechId)?.techName ?? order.assignedTechId} แล้ว` : "การมอบหมายงานต้องได้รับการเลือกและยืนยันจาก Supervisor หรือ Admin"}</div>}<div className="flex flex-wrap gap-2 border-t border-white/10 pt-4">{order.statusCode === "ASSIGNED" && ["TECHNICIAN", "SUPERVISOR", "ADMIN"].includes(user?.role ?? "") && <Button onClick={() => go("IN_PROGRESS")} disabled={change.isPending} className="h-10 rounded-xl bg-amber-400 text-slate-950 hover:bg-amber-300">เริ่มงาน</Button>}{["IN_PROGRESS", "PENDING_PARTS"].includes(order.statusCode) && ["TECHNICIAN", "SUPERVISOR", "ADMIN"].includes(user?.role ?? "") && <Button onClick={() => go("COMPLETED")} disabled={change.isPending} className="h-10 rounded-xl bg-emerald-400 text-slate-950 hover:bg-emerald-300">ทำเครื่องหมายว่าเสร็จ</Button>}{order.statusCode === "COMPLETED" && isManager && <Button onClick={() => go("CLOSED")} disabled={change.isPending} className="h-10 rounded-xl bg-slate-200 text-slate-950 hover:bg-white">ปิดใบงาน</Button>}{order.statusCode === "PENDING_PARTS" && <PendingPartsPdf order={order} />}<Button variant="outline" onClick={onClose} className="h-10 rounded-xl border-white/15 bg-transparent text-slate-100 hover:bg-white/10">ปิด</Button></div></div></DialogContent></Dialog>;
}

function WorkOrders({ orders, locations, technicians, search, setSearch, status, setStatus, onSelect }: { orders: any[]; locations: any[]; technicians: any[]; search: string; setSearch: (value: string) => void; status: string; setStatus: (value: string) => void; onSelect: (id: string) => void }) { return <Card className="border-white/10 bg-slate-950/60 text-slate-100 shadow-sm"><CardHeader className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><CardTitle>ใบงานทั้งหมด</CardTitle><p className="mt-1 text-xs text-slate-400">แตะรายการเพื่อดูรูป หลักฐาน การมอบหมาย และการเบิกอะไหล่</p></div><div className="grid w-full grid-cols-[1fr_auto] gap-2 sm:w-auto"><div className="flex h-10 min-w-0 items-center gap-2 rounded-xl border border-white/10 bg-white/[.04] px-3"><Search className="h-4 w-4 text-slate-400" /><input value={search} onChange={event => setSearch(event.target.value)} className="min-w-0 flex-1 bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-500" placeholder="ค้นหาใบงาน" /></div><select value={status} onChange={event => setStatus(event.target.value)} className="h-10 rounded-xl border border-white/10 bg-slate-900 px-2 text-xs"><option value="ALL">ทุกสถานะ</option>{Object.entries(statusLabels).map(([code, label]) => <option key={code} value={code}>{label}</option>)}</select></div></CardHeader><CardContent className="p-0"><div className="hidden overflow-x-auto md:block"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-white/[.04] text-[10px] font-bold tracking-wide text-slate-400"><tr><th className="px-6 py-3">ใบงาน</th><th className="px-4 py-3">พื้นที่</th><th className="px-4 py-3">ผู้รับผิดชอบ</th><th className="px-4 py-3">สถานะ</th><th className="px-6 py-3 text-right">วันที่</th></tr></thead><tbody>{orders.map(order => <tr key={order.woId} className="cursor-pointer border-t border-white/[.07] transition hover:bg-white/[.04]" onClick={() => onSelect(order.woId)}><td className="px-6 py-4"><p className="font-bold text-white">{order.woId}</p><p className="mt-1 max-w-[300px] truncate text-xs text-slate-400">{order.description}</p></td><td className="px-4 py-4 text-xs text-slate-300">{locations.find(location => location.locationId === order.locationId)?.areaName ?? order.locationId}</td><td className="px-4 py-4 text-xs text-slate-300">{technicians.find(technician => technician.techId === order.assignedTechId)?.techName ?? "ยังไม่มอบหมาย"}</td><td className="px-4 py-4"><StatusPill status={order.statusCode} /></td><td className="px-6 py-4 text-right text-xs text-slate-400">{formatDate(order.createdAt, true)}</td></tr>)}</tbody></table></div><div className="space-y-2 p-3 md:hidden">{orders.map(order => <button key={order.woId} onClick={() => onSelect(order.woId)} className="w-full rounded-2xl border border-white/10 bg-white/[.035] p-3 text-left"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="text-xs font-bold text-white">{order.woId}</p><p className="mt-1 line-clamp-2 text-xs leading-5 text-slate-300">{order.description}</p></div><StatusPill status={order.statusCode} /></div><div className="mt-3 flex flex-wrap gap-2 text-[10px] text-slate-400"><span className="inline-flex items-center gap-1"><MapPin className="h-3 w-3" />{locations.find(location => location.locationId === order.locationId)?.areaName ?? order.locationId}</span><span className="ml-auto">{formatDate(order.createdAt)}</span></div></button>)}</div>{orders.length === 0 && <p className="p-10 text-center text-sm text-slate-400">ไม่พบใบงาน</p>}</CardContent></Card>; }

function UserManagement({ currentUserId }: { currentUserId: string }) { const { user } = useAuth(); const utils = trpc.useUtils(); const isAdmin = user?.role === "ADMIN"; const [editing, setEditing] = useState<any>(null); const listQuery = trpc.users.list.useQuery({}, { enabled: isAdmin }); const update = trpc.users.update.useMutation({ onSuccess: async () => { setEditing(null); await Promise.all([utils.users.list.invalidate(), utils.technicians.list.invalidate()]); toast.success("บันทึกข้อมูลผู้ใช้งานแล้ว"); }, onError: error => toast.error(`บันทึกไม่สำเร็จ: ${error.message}`) }); if (!isAdmin) return <AccessNotice title="ส่วนนี้สำหรับผู้ดูแลระบบ">ผู้ที่มีสิทธิ์ ADMIN เท่านั้นที่กำหนดบทบาทและจัดการข้อมูลผู้ใช้งานได้</AccessNotice>; return <div className="space-y-4"><Card className="border-teal-300/15 bg-teal-400/[.08] text-slate-100"><CardContent className="flex gap-3 p-5"><ShieldCheck className="h-8 w-8 text-teal-200" /><div><p className="font-bold">จัดการผู้ใช้งานและบทบาท</p><p className="mt-1 text-sm text-slate-300">กำหนด TECHNICIAN เพื่อเพิ่มในหน้าช่าง หรือกำหนด SUPERVISOR/ADMIN เพื่อให้ผู้ใช้มอบหมายงานได้</p></div></CardContent></Card><div className="space-y-2">{(listQuery.data ?? []).map((item: any) => <Card key={item.userId} className="border-white/10 bg-slate-950/60 text-slate-100"><CardContent className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center overflow-hidden rounded-full bg-teal-300/10 text-xs font-bold text-teal-200">{item.pictureUrl ? <img src={item.pictureUrl} alt="" className="h-full w-full object-cover" /> : initials(item.displayName)}</div><div><p className="font-bold">{item.displayName}</p><p className="text-xs text-slate-400">{item.department ?? "ไม่ระบุแผนก"}</p></div></div><div className="flex items-center gap-2"><span className="rounded-full bg-violet-400/15 px-2 py-1 text-[10px] font-bold text-violet-200">{roleLabels[item.roleCode] ?? item.roleCode}</span><Button size="sm" variant="outline" className="h-9 border-white/15 bg-transparent text-slate-100 hover:bg-white/10" onClick={() => setEditing({ ...item })}>แก้ไข</Button></div></CardContent></Card>)}</div><Dialog open={Boolean(editing)} onOpenChange={open => !open && setEditing(null)}><DialogContent className="w-[calc(100%-2rem)] rounded-2xl border-white/10 bg-slate-950 text-slate-100 sm:max-w-lg"><DialogHeader><DialogTitle>แก้ไขผู้ใช้งาน</DialogTitle></DialogHeader>{editing && <form className="space-y-4 pt-3" onSubmit={event => { event.preventDefault(); update.mutate({ userId: editing.userId, values: { displayName: editing.displayName, department: editing.department || null, roleCode: editing.roleCode, isActive: Boolean(editing.isActive), notes: editing.notes || null } }); }}><label className="block text-sm font-semibold">ชื่อที่แสดง<Input value={editing.displayName ?? ""} onChange={event => setEditing({ ...editing, displayName: event.target.value })} className="mt-2 border-white/10 bg-slate-900 text-white" /></label><label className="block text-sm font-semibold">แผนก<select value={editing.department ?? ""} onChange={event => setEditing({ ...editing, department: event.target.value })} className="mt-2 h-11 w-full rounded-xl border border-white/10 bg-slate-900 px-3 text-sm text-white"><option value="">ไม่ระบุแผนก</option><option value="FRONT_OFFICE">แผนกต้อนรับ</option><option value="HOUSEKEEPING">แผนกแม่บ้าน</option><option value="FOOD_AND_BEVERAGE">แผนกอาหารและเครื่องดื่ม</option><option value="ENGINEERING">แผนกช่างและวิศวกรรม</option><option value="SECURITY">แผนกรักษาความปลอดภัย</option><option value="FINANCE">แผนกการเงิน</option><option value="ADMINISTRATION">แผนกบริหาร</option><option value="OTHER">อื่น ๆ</option>{editing.department && !["FRONT_OFFICE", "HOUSEKEEPING", "FOOD_AND_BEVERAGE", "ENGINEERING", "SECURITY", "FINANCE", "ADMINISTRATION", "OTHER"].includes(editing.department) && <option value={editing.department}>{editing.department}</option>}</select></label><label className="block text-sm font-semibold">บทบาท<select disabled={editing.userId === currentUserId} value={editing.roleCode} onChange={event => setEditing({ ...editing, roleCode: event.target.value })} className="mt-2 h-11 w-full rounded-xl border border-white/10 bg-slate-900 px-3 text-sm">{Object.entries(roleLabels).map(([code, label]) => <option key={code} value={code}>{label} ({code})</option>)}</select></label><label className="flex items-center gap-3 rounded-xl bg-white/[.04] p-3 text-sm font-semibold"><input type="checkbox" disabled={editing.userId === currentUserId} checked={Boolean(editing.isActive)} onChange={event => setEditing({ ...editing, isActive: event.target.checked })} /> เปิดใช้งานบัญชี</label><div className="flex justify-end gap-2"><Button type="button" variant="outline" className="border-white/15 bg-transparent text-white hover:bg-white/10" onClick={() => setEditing(null)}>ยกเลิก</Button><Button type="submit" className="bg-teal-300 text-slate-950 hover:bg-teal-200" disabled={update.isPending}>บันทึก</Button></div></form>}</DialogContent></Dialog></div>; }

function LineSettings() { const { user } = useAuth(); const utils = trpc.useUtils(); const isAdmin = user?.role === "ADMIN"; const setting = trpc.integrations.line.settings.useQuery(undefined, { enabled: isAdmin }); const [token, setToken] = useState(""); const [recipient, setRecipient] = useState(""); const [isEnabled, setEnabled] = useState(false); const save = trpc.integrations.line.save.useMutation({ onSuccess: async () => { await utils.integrations.line.settings.invalidate(); setToken(""); setRecipient(""); toast.success("บันทึกการตั้งค่า LINE แล้ว"); }, onError: error => toast.error(`บันทึกไม่สำเร็จ: ${error.message}`) }); useEffect(() => { if (setting.data) setEnabled(setting.data.isEnabled); }, [setting.data]); if (!isAdmin) return <AccessNotice title="การตั้งค่าสำหรับ ADMIN">ผู้ดูแลระบบเท่านั้นที่ตั้งค่า LINE Messaging API และปลายทาง Google Drive ได้</AccessNotice>; return <div className="grid gap-5 xl:grid-cols-2"><Card className="border-white/10 bg-slate-950/60 text-slate-100"><CardHeader><CardTitle>LINE Messaging API</CardTitle><p className="text-xs text-slate-400">ข้อมูลสำคัญถูกเข้ารหัสก่อนบันทึก</p></CardHeader><CardContent><form className="space-y-4" onSubmit={event => { event.preventDefault(); save.mutate({ channelAccessToken: token || undefined, recipientId: recipient || undefined, isEnabled, alertUrgent: true, alertOverdue: true }); }}><label className="block text-sm font-semibold">Channel Access Token<Input type="password" value={token} onChange={event => setToken(event.target.value)} placeholder={setting.data?.tokenMasked ?? "ใส่ token"} className="mt-2 h-11 border-white/10 bg-slate-900 text-white" /></label><label className="block text-sm font-semibold">User ID หรือ Group ID<Input value={recipient} onChange={event => setRecipient(event.target.value)} placeholder={setting.data?.recipientMasked ?? "Uxxxxxxxx"} className="mt-2 h-11 border-white/10 bg-slate-900 text-white" /></label><label className="flex items-center justify-between gap-3 rounded-xl bg-white/[.04] p-3 text-sm"><span>เปิดแจ้งเตือน LINE</span><input type="checkbox" checked={isEnabled} onChange={event => setEnabled(event.target.checked)} /></label><Button type="submit" disabled={save.isPending} className="w-full bg-teal-300 text-slate-950 hover:bg-teal-200">{save.isPending ? "กำลังบันทึก..." : "บันทึกการตั้งค่า"}</Button></form></CardContent></Card><GoogleDriveSettings /></div>; }

export default function HotelOperationsHome({ onCreateWorkOrder = () => undefined, onOpenPartsManager = () => undefined }: { onCreateWorkOrder?: () => void; onOpenPartsManager?: () => void }) {
  const { user, loading, refresh } = useAuth(); const [section, setSection] = useState("overview"); const [menuOpen, setMenuOpen] = useState(false); const [search, setSearch] = useState(""); const [status, setStatus] = useState("ALL"); const [selectedId, setSelectedId] = useState<string | null>(null); const [authTimeout, setAuthTimeout] = useState(false);
  useEffect(() => { if (!loading) return; const timeout = window.setTimeout(() => setAuthTimeout(true), 7000); return () => window.clearTimeout(timeout); }, [loading]);
  const profile = trpc.profile.me.useQuery(undefined, { enabled: Boolean(user) }); const [profileTimeout, setProfileTimeout] = useState(false); useEffect(() => { if (!user || !profile.isLoading) { setProfileTimeout(false); return; } const timeout = window.setTimeout(() => setProfileTimeout(true), 7000); return () => window.clearTimeout(timeout); }, [user, profile.isLoading]); const stats = trpc.dashboard.stats.useQuery(undefined, { enabled: Boolean(user) }); const ordersQuery = trpc.workOrders.list.useQuery({ search: search || undefined, status: status === "ALL" ? undefined : status }, { enabled: Boolean(user) }); const locations = trpc.locations.list.useQuery(undefined, { enabled: Boolean(user) }); const technicians = trpc.technicians.list.useQuery(undefined, { enabled: Boolean(user) }); const detail = trpc.workOrders.detail.useQuery({ woId: selectedId ?? "" }, { enabled: Boolean(selectedId) }); const upload = trpc.workOrders.uploadAttachment.useMutation({ onSuccess: () => detail.refetch(), onError: error => toast.error(`แนบรูปไม่สำเร็จ: ${error.message}`) }); const complete = trpc.profile.completeRegistration.useMutation({ onSuccess: () => profile.refetch() });
  const orders = ordersQuery.data ?? []; const techRows = technicians.data ?? []; const locationRows = locations.data ?? []; const selected = orders.find(order => order.woId === selectedId); const isAdmin = user?.role === "ADMIN"; const statusCounts = useMemo(() => Object.fromEntries((stats.data?.byStatus ?? []).map((item: any) => [item.status, Number(item.count)])), [stats.data]);
  const uploadPhoto = (event: React.ChangeEvent<HTMLInputElement>, type: "BEFORE" | "AFTER" | "OTHER") => { const files = Array.from(event.target.files ?? []); if (!files.length || !selected || !user) return; for (const file of files) { const reader = new FileReader(); reader.onload = () => { if (typeof reader.result === "string") upload.mutate({ woId: selected.woId, attachmentType: type, fileName: file.name, mimeType: file.type || "image/jpeg", fileDataBase64: reader.result, uploadedBy: user.openId }); }; reader.readAsDataURL(file); } event.target.value = ""; };
  const authScreen = getAuthScreenState({ authLoading: loading, authWaitExpired: authTimeout, hasUser: Boolean(user), profileLoading: profile.isLoading, profileWaitExpired: profileTimeout, profileFailed: profile.isError, needsRegistration: Boolean(profile.data?.needsRegistration) }); if (authScreen === "AUTH_LOADING") return <LoginShell><p className="text-sm text-slate-300">กำลังตรวจสอบการเข้าสู่ระบบ...</p></LoginShell>; if (authScreen === "AUTH_RECOVERY") return <LoginShell><h1 className="text-xl font-bold">ยังตรวจสอบการเข้าสู่ระบบไม่สำเร็จ</h1><p className="mt-2 text-sm text-slate-300">ลองตรวจสอบใหม่ หรือเข้าสู่ระบบ LINE อีกครั้ง</p><div className="mt-5 flex gap-2"><Button variant="outline" className="border-white/15 bg-transparent text-white" onClick={() => { setAuthTimeout(false); refresh(); }}>ลองใหม่</Button><a className="rounded-xl bg-[#06C755] px-4 py-2 text-sm font-bold text-white" href="/api/auth/line/start">เข้าสู่ระบบ LINE</a></div></LoginShell>; if (authScreen === "LOGIN") return <LoginScreen />; if (authScreen === "PROFILE_LOADING") return <LoginShell><p className="text-sm text-slate-300">กำลังเตรียมข้อมูลผู้ใช้งาน...</p></LoginShell>; if (authScreen === "PROFILE_RECOVERY") return <LoginShell><h1 className="text-xl font-bold">ยังตรวจข้อมูลผู้ใช้งานไม่สำเร็จ</h1><p className="mt-2 text-sm text-slate-300">กรุณาลองใหม่ หากยังไม่สำเร็จให้เข้าสู่ระบบ LINE อีกครั้ง</p><div className="mt-5 flex gap-2"><Button variant="outline" className="border-white/15 bg-transparent text-white" onClick={() => { setProfileTimeout(false); profile.refetch(); }}>ลองใหม่</Button><a className="rounded-xl bg-[#06C755] px-4 py-2 text-sm font-bold text-white" href="/api/auth/line/start">เข้าสู่ระบบ LINE</a></div></LoginShell>; if (authScreen === "REGISTRATION") return <Registration name={user?.name ?? ""} pending={complete.isPending} error={complete.error?.message} onSubmit={event => { event.preventDefault(); const form = new FormData(event.currentTarget); complete.mutate({ displayName: String(form.get("displayName")), department: String(form.get("department")) }); }} />;
  if (!user) return <LoginScreen />;
  const nav = [{ id: "overview", label: "ภาพรวม", icon: LayoutDashboard }, { id: "orders", label: "ใบงาน", icon: ClipboardList }, { id: "parts", label: "อะไหล่", icon: PackageOpen }, { id: "technicians", label: "ช่าง", icon: Wrench }, ...(isAdmin ? [{ id: "users", label: "ผู้ใช้งาน", icon: Users2 }] : []), { id: "settings", label: "ตั้งค่า", icon: Settings2 }];
  const statCards = [{ label: "ใบงานทั้งหมด", value: stats.data?.total ?? 0, icon: ClipboardList, tone: "text-sky-200 bg-sky-400/10" }, { label: "เปิดใหม่วันนี้", value: stats.data?.today ?? 0, icon: Plus, tone: "text-violet-200 bg-violet-400/10" }, { label: "กำลังดำเนินการ", value: statusCounts.IN_PROGRESS ?? 0, icon: Clock3, tone: "text-amber-100 bg-amber-400/10" }, { label: "Pending Parts", value: statusCounts.PENDING_PARTS ?? 0, icon: PackageOpen, tone: "text-orange-100 bg-orange-400/10" }];
  const activeNav = nav.find(item => item.id === section) ?? nav[0];
  const sectionDescriptions: Record<string, string> = {
    overview: "ภาพรวมการดำเนินงานและสถานะงานซ่อมทั้งหมด",
    orders: "ค้นหา ติดตาม และจัดการใบงานซ่อม",
    parts: "ตรวจสอบสต็อกและรายการเบิกอะไหล่",
    technicians: "ทีมช่างและสถานะการเข้าเวร",
    users: "จัดการบัญชีและสิทธิ์การใช้งาน",
    settings: "การเชื่อมต่อและการตั้งค่าระบบ",
  };
  return <div className="ops-workspace min-h-screen text-slate-100">
    {menuOpen && <button aria-label="ปิดเมนู" className="fixed inset-0 z-40 bg-slate-950/70 backdrop-blur-sm lg:hidden" onClick={() => setMenuOpen(false)} />}
    <aside className={cn("ops-sidebar fixed inset-y-0 left-0 z-50 flex w-[278px] flex-col border-r border-white/10 px-4 py-5 transition-transform duration-300 lg:translate-x-0", menuOpen ? "translate-x-0" : "-translate-x-full")}>
      <div className="flex items-center gap-3 px-2">
        <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-indigo-400 to-violet-500 text-white shadow-lg shadow-indigo-950/50"><Wrench className="h-5 w-5" /></div>
        <div className="min-w-0"><p className="text-[10px] font-bold tracking-[.2em] text-indigo-300">NORTHSTAR HOTEL</p><p className="truncate text-sm font-bold text-white">Engineering Hub</p></div>
        <button aria-label="ปิดเมนู" className="ml-auto rounded-lg p-2 text-slate-400 hover:bg-white/10 lg:hidden" onClick={() => setMenuOpen(false)}><X className="h-4 w-4" /></button>
      </div>
      <div className="mx-2 mt-8 rounded-xl border border-indigo-300/15 bg-indigo-400/[.07] px-3 py-3">
        <p className="text-[10px] font-semibold uppercase tracking-[.16em] text-indigo-200/70">Workspace</p>
        <p className="mt-1 text-xs font-semibold text-slate-100">Maintenance operations</p>
        <p className="mt-1 text-[11px] text-slate-400">ระบบแจ้งซ่อมและติดตามงาน</p>
      </div>
      <nav className="mt-7 flex-1 space-y-1">
        <p className="px-3 pb-2 text-[10px] font-bold uppercase tracking-[.16em] text-slate-500">เมนูหลัก</p>
        {nav.map(item => <button key={item.id} onClick={() => { setSection(item.id); setMenuOpen(false); }} className={cn("group flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-[13px] font-medium transition-all", section === item.id ? "bg-indigo-500/15 text-indigo-100 ring-1 ring-inset ring-indigo-300/20 shadow-lg shadow-indigo-950/20" : "text-slate-400 hover:bg-white/[.05] hover:text-slate-100")}><span className={cn("flex h-8 w-8 items-center justify-center rounded-lg transition-colors", section === item.id ? "bg-indigo-400/15 text-indigo-200" : "bg-white/[.035] text-slate-500 group-hover:text-slate-200")}><item.icon className="h-[17px] w-[17px]" /></span><span className="flex-1">{item.label}</span>{section === item.id && <span className="h-1.5 w-1.5 rounded-full bg-indigo-300" />}</button>)}
      </nav>
      <div className="rounded-xl border border-white/[.08] bg-white/[.035] p-3">
        <div className="flex items-center gap-3">
          <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-indigo-300/25 to-violet-400/20 text-xs font-bold text-indigo-100">{initials(user.name)}</div>
          <div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold text-slate-100">{profile.data?.profile?.displayName ?? user.name}</p><p className="mt-0.5 truncate text-[10px] text-slate-500">{roleLabels[user.role ?? ""] ?? user.role}</p></div>
          <ShieldCheck className="h-4 w-4 text-emerald-300/70" />
        </div>
      </div>
      <p className="px-2 pt-4 text-[10px] text-slate-600">ENGINEERING WORK ORDER · v1.0</p>
    </aside>
    <div className="min-h-screen lg:pl-[278px]">
      <header className="ops-topbar sticky top-0 z-30 flex min-h-[76px] items-center justify-between gap-3 border-b border-white/[.07] px-4 py-3 sm:px-7">
        <div className="flex min-w-0 items-center gap-3">
          <button aria-label="เปิดเมนู" className="rounded-xl border border-white/10 bg-white/[.04] p-2.5 text-slate-300 hover:bg-white/10 lg:hidden" onClick={() => setMenuOpen(true)}><Menu className="h-5 w-5" /></button>
          <div className="min-w-0"><div className="flex items-center gap-2 text-[11px] text-slate-500"><span>Workspace</span><span>/</span><span className="text-indigo-300">{activeNav.label}</span></div><h1 className="mt-1 truncate text-lg font-bold tracking-tight text-white sm:text-xl">{section === "overview" ? "Operations overview" : activeNav.label}</h1></div>
        </div>
        <div className="flex shrink-0 items-center gap-2 sm:gap-3">
          <div className="hidden items-center gap-2 rounded-xl border border-white/[.08] bg-white/[.03] px-3 py-2 text-[11px] text-slate-400 md:flex"><span className="h-1.5 w-1.5 rounded-full bg-emerald-400 shadow-[0_0_10px_rgba(52,211,153,.7)]" />ระบบพร้อมใช้งาน</div>
          <Button onClick={onCreateWorkOrder} className="h-10 rounded-xl bg-indigo-500 px-3 text-xs font-bold text-white shadow-lg shadow-indigo-950/40 hover:bg-indigo-400 sm:px-4 sm:text-sm"><Plus className="mr-1.5 h-4 w-4" />สร้างใบงาน</Button>
        </div>
      </header>
      <main className="mx-auto w-full max-w-[1500px] p-4 sm:p-6 lg:p-8">
        {section === "overview" && <div className="space-y-7">
          <div className="flex flex-col justify-between gap-4 xl:flex-row xl:items-end">
            <div><p className="text-[10px] font-bold uppercase tracking-[.2em] text-indigo-300">Dashboard / Engineering</p><h2 className="mt-2 text-2xl font-bold tracking-tight text-white sm:text-[30px]">ภาพรวมงานซ่อมบำรุง</h2><p className="mt-2 text-sm text-slate-400">ติดตามภาพรวมใบงาน ประสิทธิภาพทีมช่าง และงานที่ต้องดำเนินการ</p></div>
            <div className="flex items-center gap-2 self-start rounded-xl border border-white/[.08] bg-white/[.03] px-3 py-2.5 text-xs text-slate-400 xl:self-auto"><Clock3 className="h-4 w-4 text-indigo-300" />ข้อมูลล่าสุดจากระบบ</div>
          </div>
          <div className="grid gap-3 sm:grid-cols-2 2xl:grid-cols-4">{statCards.map((stat, index) => <Card key={stat.label} className="ops-stat-card overflow-hidden border-white/[.08] bg-[#111a33] text-slate-100"><CardContent className="relative flex items-center justify-between p-5"><div><p className="text-xs font-medium text-slate-400">{stat.label}</p><p className="mt-2 text-3xl font-bold tracking-tight text-white">{stat.value}</p><p className="mt-2 text-[10px] text-slate-500">{index === 0 ? "รายการในระบบ" : index === 1 ? "รายการที่รับแจ้งวันนี้" : index === 2 ? "อยู่ระหว่างดำเนินการ" : "รอการจัดหาอะไหล่"}</p></div><div className={cn("flex h-12 w-12 items-center justify-center rounded-2xl ring-1 ring-inset ring-white/10", stat.tone)}><stat.icon className="h-5 w-5" /></div><div className="pointer-events-none absolute -bottom-8 -right-5 h-24 w-24 rounded-full bg-indigo-500/[.06] blur-2xl" /></CardContent></Card>)}</div>
          <div className="grid gap-4 2xl:grid-cols-[minmax(0,1.65fr)_minmax(260px,.75fr)]">
            <Card className="overflow-hidden border-white/[.08] bg-[#111a33] text-slate-100"><CardHeader className="flex flex-row items-center justify-between border-b border-white/[.06] px-5 py-4"><div><CardTitle className="text-sm font-bold text-white">รายการใบงานล่าสุด</CardTitle><p className="mt-1 text-[11px] text-slate-500">รายการแจ้งซ่อมที่อัปเดตล่าสุด</p></div><Button variant="outline" onClick={() => setSection("orders")} className="h-8 rounded-lg border-white/10 bg-white/[.03] text-xs text-slate-300 hover:bg-white/10">ดูใบงานทั้งหมด <ArrowUpRight className="ml-1 h-3.5 w-3.5" /></Button></CardHeader><CardContent className="p-3 sm:p-5"><WorkOrders orders={orders.slice(0, 6)} locations={locationRows} technicians={techRows} search="" setSearch={() => undefined} status="ALL" setStatus={() => undefined} onSelect={setSelectedId} /></CardContent></Card>
            <div className="space-y-4">
              <Card className="border-white/[.08] bg-[#111a33] text-slate-100"><CardHeader className="pb-3"><CardTitle className="text-sm font-bold">สถานะใบงาน</CardTitle><p className="text-[11px] text-slate-500">สรุปจำนวนตามขั้นตอน</p></CardHeader><CardContent className="space-y-3">{[{code:"OPEN",label:"เปิดงาน",color:"bg-sky-400"},{code:"ASSIGNED",label:"มอบหมายแล้ว",color:"bg-violet-400"},{code:"IN_PROGRESS",label:"กำลังดำเนินการ",color:"bg-amber-400"},{code:"PENDING_PARTS",label:"รออะไหล่",color:"bg-orange-400"},{code:"COMPLETED",label:"เสร็จงาน",color:"bg-emerald-400"}].map(item => { const count = statusCounts[item.code] ?? 0; const total = Math.max(1, stats.data?.total ?? 0); return <div key={item.code}><div className="mb-1.5 flex items-center justify-between text-xs"><span className="text-slate-400">{item.label}</span><span className="font-semibold tabular-nums text-slate-200">{count}</span></div><div className="h-1.5 overflow-hidden rounded-full bg-white/[.06]"><div className={cn("h-full rounded-full",item.color)} style={{width:`${Math.min(100,count/total*100)}%`}} /></div></div>; })}</CardContent></Card>
              <Card className="border-indigo-300/15 bg-gradient-to-br from-indigo-500/[.13] to-violet-500/[.06] text-slate-100"><CardContent className="p-5"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-indigo-300/15 text-indigo-200"><Bell className="h-4 w-4" /></div><p className="mt-3 text-sm font-bold text-white">การแจ้งเตือนระบบ</p><p className="mt-1 text-xs leading-5 text-slate-400">LINE แจ้งเตือนเหตุเร่งด่วนและงานเกินกำหนด ตามการตั้งค่าของผู้ดูแลระบบ</p><button onClick={() => setSection("settings")} className="mt-3 text-xs font-semibold text-indigo-300 hover:text-indigo-200">ตรวจสอบการตั้งค่า <span aria-hidden="true">→</span></button></CardContent></Card>
            </div>
          </div>
        </div>}
        {section === "orders" && <div className="space-y-5"><div><p className="text-[10px] font-bold uppercase tracking-[.2em] text-indigo-300">Work management</p><h2 className="mt-2 text-2xl font-bold text-white">ใบงานซ่อม</h2><p className="mt-1 text-sm text-slate-400">{sectionDescriptions.orders}</p></div><WorkOrders orders={orders} locations={locationRows} technicians={techRows} search={search} setSearch={setSearch} status={status} setStatus={setStatus} onSelect={setSelectedId} /></div>}
        {section === "technicians" && <div className="space-y-5"><div><p className="text-[10px] font-bold uppercase tracking-[.2em] text-indigo-300">Team management</p><h2 className="text-2xl font-bold text-white">ทีมช่าง</h2><p className="mt-1 text-sm text-slate-400">{sectionDescriptions.technicians}</p></div><TechnicianPanel technicians={techRows} /></div>}
        {section === "parts" && <div className="space-y-5"><div><p className="text-[10px] font-bold uppercase tracking-[.2em] text-indigo-300">Inventory</p><h2 className="text-2xl font-bold text-white">คลังอะไหล่</h2><p className="mt-1 text-sm text-slate-400">{sectionDescriptions.parts}</p></div><Card className="border-orange-300/15 bg-orange-400/[.07] text-slate-100"><CardContent className="p-6"><PackageOpen className="h-8 w-8 text-orange-200" /><h2 className="mt-4 text-lg font-bold">คลังอะไหล่และวัสดุ</h2><p className="mt-2 max-w-xl text-sm leading-6 text-slate-300">จัดการข้อมูลคลัง อนุมัติคำขอ และจ่ายอะไหล่ ส่วนการขอเบิกให้ทำจากรายละเอียดใบงาน เพื่อผูกเลขใบงานให้อัตโนมัติ</p><Button onClick={onOpenPartsManager} className="mt-5 bg-orange-400 text-slate-950 hover:bg-orange-300">เปิดคลังอะไหล่</Button></CardContent></Card></div>}
        {section === "users" && <div className="space-y-5"><div><p className="text-[10px] font-bold uppercase tracking-[.2em] text-indigo-300">Access control</p><h2 className="text-2xl font-bold text-white">ผู้ใช้งานและสิทธิ์</h2><p className="mt-1 text-sm text-slate-400">{sectionDescriptions.users}</p></div><UserManagement currentUserId={user.openId} /></div>}
        {section === "settings" && <div className="space-y-5"><div><p className="text-[10px] font-bold uppercase tracking-[.2em] text-indigo-300">System settings</p><h2 className="text-2xl font-bold text-white">ตั้งค่าระบบ</h2><p className="mt-1 text-sm text-slate-400">{sectionDescriptions.settings}</p></div><LineSettings /></div>}
      </main>
    </div>
    {selected && <WorkOrderDetail order={selected} locations={locationRows} technicians={techRows} data={detail.data} onClose={() => setSelectedId(null)} onUpload={uploadPhoto} />}
  </div>;
}
